// Package clock provides the server time source. Timestamps are generated by
// the server, in UTC, truncated to PostgreSQL's microsecond precision so
// values read back compare equal to values written.
package clock

import "time"

// Clock returns the current instant.
type Clock func() time.Time

// System is the real clock.
func System() time.Time {
	return Normalize(time.Now())
}

// Normalize converts t to UTC with microsecond precision.
func Normalize(t time.Time) time.Time {
	return t.UTC().Truncate(time.Microsecond)
}
